import json, re, sys

def unq(s):
    s = s.strip()
    assert s.startswith('"') and s.endswith('"'), s
    s = s[1:-1]
    out=[];i=0
    while i<len(s):
        c=s[i]
        if c=='\\':
            n=s[i+1]
            out.append({'n':'\n','t':'\t','"':'"','\\':'\\'}.get(n, '\\'+n)); i+=2
        else: out.append(c); i+=1
    return ''.join(out)

def q(s):
    return '"' + s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t') + '"'

def parse(path):
    text=open(path,encoding='utf-8').read()
    blocks=text.split('\n\n')
    ents=[]
    for bi,b in enumerate(blocks):
        lines=b.strip('\n').split('\n')
        if not any(l.startswith('msgid ') for l in lines): continue
        e={'block':bi,'comments':[],'flags':'','ctxt':None,'id':None,'plural':None,'nstr':0}
        cur=None; vals={}
        for l in lines:
            if l.startswith('#'):
                if l.startswith('#.') or l.startswith('#:'): e['comments'].append(l)
                if l.startswith('#,'): e['flags']=l
                cur=None; continue
            m=re.match(r'^(msgctxt|msgid_plural|msgid|msgstr(?:\[\d\])?) (".*")$',l)
            if m:
                cur=m.group(1); vals[cur]=unq(m.group(2))
            else:
                vals[cur]+=unq(l)
        e['ctxt']=vals.get('msgctxt'); e['id']=vals['msgid']; e['plural']=vals.get('msgid_plural')
        e['str']=vals.get('msgstr', None)
        e['strs']=[vals[k] for k in sorted(vals) if k.startswith('msgstr[')]
        ents.append(e)
    return blocks, ents

if __name__=='__main__':
    blocks,ents=parse(sys.argv[1])
    out=[]
    for i,e in enumerate(ents):
        if e['id']=='' : continue
        d={'i':i,'id':e['id']}
        if e['plural']: d['pl']=e['plural']
        if e['ctxt'] is not None: d['ctx']=e['ctxt']
        c=[x for x in e['comments'] if x.startswith('#.')]
        if c: d['c']=' | '.join(x[3:] for x in c)
        src=[x[3:] for x in e['comments'] if x.startswith('#:')]
        if src: d['src']=' '.join(src)
        out.append(d)
    json.dump(out, open(sys.argv[2],'w',encoding='utf-8'), ensure_ascii=False, indent=0)
    print(len(out))
EOF
